-- EFY 발표용 MariaDB 시드. 현재 엔티티로 만든 빈 DB에만 수동으로 한 번 적용합니다.
-- 기존 data.sql·운영 자동 초기화 설정은 변경하지 않습니다. 실행 방법: docs/mariadb-seed.md
-- 공통 비밀번호 12341234는 공개 데모 전용입니다. 실제 개인정보·결제·파일은 사용하지 않습니다.
-- 한 연결에서 파일 전체를 실행하며 오류 발생 시 즉시 중단하고 ROLLBACK 합니다. --force 금지.
-- 외래 키를 끄거나 기존 데이터를 삭제하지 않습니다. 재실행·부분 실행·기존 DB 병합은 지원하지 않습니다.
SET NAMES utf8mb4;
SET time_zone = '+09:00';
SET @seed_now = CURRENT_TIMESTAMP;
CREATE TEMPORARY TABLE seed174_empty_guard (row_count BIGINT CHECK (row_count = 0));
START TRANSACTION;

INSERT INTO seed174_empty_guard (row_count)
SELECT (SELECT COUNT(*) FROM first_category)
     + (SELECT COUNT(*) FROM second_category)
     + (SELECT COUNT(*) FROM first_region)
     + (SELECT COUNT(*) FROM second_region)
     + (SELECT COUNT(*) FROM member)
     + (SELECT COUNT(*) FROM expert_profile)
     + (SELECT COUNT(*) FROM expert_profile_services)
     + (SELECT COUNT(*) FROM expert_profile_regions)
     + (SELECT COUNT(*) FROM expert_profile_whole_regions)
     + (SELECT COUNT(*) FROM question)
     + (SELECT COUNT(*) FROM service_request)
     + (SELECT COUNT(*) FROM request_answer)
     + (SELECT COUNT(*) FROM quote)
     + (SELECT COUNT(*) FROM credit_product)
     + (SELECT COUNT(*) FROM credit_wallet)
     + (SELECT COUNT(*) FROM credit_reservation)
     + (SELECT COUNT(*) FROM credit_history)
     + (SELECT COUNT(*) FROM chat_room)
     + (SELECT COUNT(*) FROM chat_participant)
     + (SELECT COUNT(*) FROM chat_message)
     + (SELECT COUNT(*) FROM post)
     + (SELECT COUNT(*) FROM post_comment)
     + (SELECT COUNT(*) FROM post_like)
     + (SELECT COUNT(*) FROM post_comment_like)
     + (SELECT COUNT(*) FROM bookmark)
     + (SELECT COUNT(*) FROM payment)
     + (SELECT COUNT(*) FROM file)
     + (SELECT COUNT(*) FROM work_image);

