INSERT INTO expert_profile (id, member_id, short_intro, description, career_years, career_description, primary_category_id, is_nationwide)
VALUES (1, 11, '원룸 이사, 포장부터 가구 조립까지 맡겨 주세요.', '안녕하세요. 서울에서 소형 이사를 맡고 있는 김민준입니다. 짐 사진과 이동할 곳을 보내 주시면 차량과 작업 인원부터 안내해 드려요. 침대와 책상은 구조를 확인한 뒤 분해·조립까지 도와드립니다.', 3, '원룸·오피스텔 이사 3년. 가구 분해와 재조립 작업을 함께 맡고 있습니다.', 101, FALSE),
       (2, 12, '계단이 있는 집도 짐에 맞춰 안전하게 옮깁니다.', '엘리베이터 없는 집은 계단 폭과 층수를 먼저 확인합니다. 박스에 담기 어려운 물건은 별도로 포장하고 바닥과 모서리를 보호한 뒤 옮겨요. 현장에서 비용이 달라질 수 있는 항목은 상담할 때 미리 말씀드립니다.', 4, '주택과 빌라의 소형 이사 4년. 계단 운반과 가전 포장 경험이 있습니다.', 101, FALSE),
       (3, 13, '큰 가구 하나부터 작은 집 이사까지 도와드려요.', '서울 서남권에서 가구 운반과 원룸 이사를 하고 있습니다. 냉장고와 세탁기는 설치 상태를 먼저 확인하고 운반 가능 여부를 안내합니다. 혼자 옮기기 어려운 짐이 있다면 크기와 사진을 보내 주세요.', 5, '가전·가구 운반 5년. 소형 이사와 사무실 집기 이동을 진행했습니다.', 101, FALSE),
       (4, 14, '짐 들어오기 전, 빈집 구석구석 살펴드립니다.', '입주 전에 창틀과 수납장 안쪽까지 청소합니다. 평수와 집 상태를 확인한 뒤 작업 인원과 예상 시간을 알려 드려요. 끝나면 함께 둘러보면서 부족한 곳이 없는지 확인합니다.', 6, '아파트·오피스텔 입주 청소 6년. 주방과 욕실의 오염 상태에 맞춰 작업합니다.', 102, FALSE),
       (5, 15, '주방 기름때와 욕실 물때를 꼼꼼하게 정리해요.', '눈에 잘 보이지 않는 후드 필터와 배수구까지 살핍니다. 소재를 확인하고 세제를 골라 작업하며 손상이 우려되는 부분은 먼저 설명드려요. 포함되는 작업과 별도 상담이 필요한 항목을 구분해서 안내합니다.', 7, '주거 공간 청소 7년. 주방 후드와 욕실의 묵은 오염을 다루는 작업을 맡아 왔습니다.', 102, FALSE),
       (6, 16, '청소가 끝난 뒤 함께 확인하는 시간을 갖습니다.', '상담할 때 가장 신경 쓰이는 공간부터 여쭤봅니다. 사진만으로 판단하기 어려운 오염은 현장에서 설명드리고 진행 여부를 정해요. 작업 후에는 창문과 수납장을 직접 열어 확인하실 수 있도록 안내합니다.', 8, '입주·이사 청소 8년. 구축 아파트와 장기 공실의 청소를 진행했습니다.', 102, FALSE),
       (7, 17, '필요한 기능부터 차근차근 웹으로 만듭니다.', '작은 공방과 매장의 소개·예약 사이트를 개발합니다. 사용자가 어떤 순서로 예약하는지부터 정리하고 화면과 API를 함께 만들어요. 처음부터 기능을 늘리기보다 운영에 꼭 필요한 범위를 먼저 제안드립니다.', 9, '웹 서비스 개발 9년. 예약 사이트와 소규모 사업장의 관리 화면을 구축했습니다.', 139, FALSE),
       (8, 18, '회원·예약·결제 API를 안정적으로 연결합니다.', 'Java와 Spring Boot로 백엔드를 개발하는 박현우입니다. 기존 화면이 있다면 요청·응답 형식부터 맞추고 데이터 구조를 정리합니다. 운영 중 문제를 찾기 쉽도록 로그와 기본적인 테스트도 함께 준비해요.', 10, '백엔드 개발 10년. 회원 인증과 예약 관리 API의 설계·운영을 담당했습니다.', 139, FALSE),
       (9, 19, '휴대폰에서 쓰기 편한 화면을 고민합니다.', '글자 크기와 버튼 위치처럼 사용자가 바로 느끼는 부분을 살펴봅니다. 소개 페이지부터 문의·예약 화면까지 모바일 흐름에 맞춰 개발해요. 완성 후 직접 수정하실 내용이 있다면 관리 방법도 설명드립니다.', 11, '웹 화면 개발 11년. 반응형 소개 페이지와 예약 화면을 제작했습니다.', 139, FALSE),
       (10, 20, '멀리 계셔도 온라인으로 개발 과정을 공유합니다.', '지역에 관계없이 온라인 상담으로 웹 개발을 진행합니다. 기능 목록과 일정을 합의한 뒤 작업 화면을 주기적으로 보여 드려요. 배포 후 확인할 항목과 운영에 필요한 계정도 함께 정리해 드립니다.', 12, '웹 개발 12년. 원격 협업으로 서비스 구축과 배포까지 진행했습니다.', 139, TRUE);

