-- 5. 견적 27개. 사용자2는 비교 중이고 사용자3은 4건을 의뢰하여 채팅할 수 있습니다.

INSERT INTO quote (id, expert_id, service_request_id, description, price, quote_status, sent_at)
VALUES (1, 1, 4, '안녕하세요. 김민준입니다. 원룸 이사와 침대·책상 운반을 함께 도와드릴 수 있어요. 가구 사진을 보내 주시면 분해·조립이 필요한지 확인하겠습니다.', 280000, 'SENT', DATE_SUB(@seed_now, INTERVAL 55 MINUTE)),
       (2, 2, 4, '이서준입니다. 출발지와 도착지의 층수, 엘리베이터 유무를 알려 주세요. 침대와 책상을 안전하게 옮길 수 있도록 운반 동선부터 살펴보겠습니다.', 300000, 'SENT', DATE_SUB(@seed_now, INTERVAL 55 MINUTE)),
       (3, 3, 4, '안녕하세요. 최도윤입니다. 큰 가구는 모서리를 보호해 포장하고 이동합니다. 책상 크기와 침대 프레임 사진을 보고 필요한 인원을 안내해 드릴게요.', 320000, 'SENT', DATE_SUB(@seed_now, INTERVAL 55 MINUTE)),
       (4, 4, 5, '안녕하세요. 정수빈입니다. 20평 아파트 입주 청소 가능하며 창틀과 화장실도 포함해서 살펴봅니다. 집 안이 비어 있는지 알려 주시면 작업 시간을 안내해 드릴게요.', 230000, 'SENT', DATE_SUB(@seed_now, INTERVAL 65 MINUTE)),
       (5, 5, 5, '오지안입니다. 요청하신 창틀과 화장실을 중심으로 청소 범위를 잡아 봤어요. 물때와 곰팡이 상태를 사진으로 확인하면 작업 방법을 더 구체적으로 말씀드릴 수 있습니다.', 250000, 'SENT', DATE_SUB(@seed_now, INTERVAL 65 MINUTE)),
       (6, 6, 5, '안녕하세요. 윤하윤입니다. 입주 전에 주방과 수납장 안쪽까지 확인하고 청소합니다. 특히 신경 쓰이는 공간을 알려 주시면 마무리 점검 때 함께 살펴볼게요.', 270000, 'SENT', DATE_SUB(@seed_now, INTERVAL 65 MINUTE)),
       (7, 7, 6, '안녕하세요. 강지호입니다. Spring Boot 기반 REST API 개발을 도와드릴 수 있어요. 이번 달 안에 필요한 기능을 우선순위로 정리해서 작업 범위를 맞춰 보겠습니다.', 1200000, 'SENT', DATE_SUB(@seed_now, INTERVAL 75 MINUTE)),
       (8, 8, 6, '박현우입니다. JPA와 MySQL을 사용하는 백엔드 개발 요청 확인했습니다. 기존 화면이나 API 명세가 있다면 보내 주세요. 기능별로 필요한 작업과 일정을 정리해 드리겠습니다.', 1220000, 'SENT', DATE_SUB(@seed_now, INTERVAL 75 MINUTE)),
       (9, 9, 6, '안녕하세요. 임서아입니다. 준비된 화면에 맞춰 API를 연결하는 작업도 가능합니다. 이번 견적은 기본 기능을 기준으로 잡았으며 화면 수와 상세 기능을 확인한 뒤 범위를 협의하고 싶습니다.', 1240000, 'SENT', DATE_SUB(@seed_now, INTERVAL 75 MINUTE)),
       (10, 1, 7, '김민준입니다. 침대와 책상을 포함한 원룸 짐 운반을 기준으로 견적 드렸어요. 이사 당일 바로 쓰실 물건은 별도로 챙겨 두시면 좋습니다. 가구 조립 범위는 사진을 보고 안내할게요.', 280000, 'SENT', DATE_SUB(@seed_now, INTERVAL 85 MINUTE)),
       (11, 2, 7, '안녕하세요. 이서준입니다. 이사 차량이 건물 가까이 주차할 수 있는지 먼저 확인 부탁드려요. 계단 운반이 필요하면 층수와 계단 폭에 맞춰 작업 인원을 준비하겠습니다.', 300000, 'SENT', DATE_SUB(@seed_now, INTERVAL 85 MINUTE)),
       (12, 3, 7, '최도윤입니다. 침대와 책상 외에 냉장고나 세탁기도 옮기실 예정인가요? 짐 목록을 보내 주시면 운반 가능한 크기와 포장 방법을 확인해 드리겠습니다.', 320000, 'SENT', DATE_SUB(@seed_now, INTERVAL 85 MINUTE)),
       (13, 4, 8, '정수빈입니다. 요청하신 입주 청소에서 창틀 홈과 욕실 배수구를 중점적으로 확인하겠습니다. 가구가 먼저 들어오는 일정이라면 위치를 알려 주세요. 접근 가능한 범위를 설명드릴게요.', 230000, 'SENT', DATE_SUB(@seed_now, INTERVAL 95 MINUTE)),
       (14, 5, 8, '안녕하세요. 오지안입니다. 화장실의 타일과 수전 상태를 먼저 보고 소재에 맞게 작업합니다. 창틀 사진도 함께 보내 주시면 추가 상담이 필요한 부분을 미리 안내해 드릴게요.', 250000, 'SENT', DATE_SUB(@seed_now, INTERVAL 95 MINUTE)),
       (15, 6, 8, '윤하윤입니다. 빈집 입주 청소를 기준으로 제안드립니다. 작업을 마친 뒤 창문과 수납장을 열어 함께 확인하는 시간을 갖고 있어요. 입주 일정에 맞춰 상담해 보겠습니다.', 270000, 'SENT', DATE_SUB(@seed_now, INTERVAL 95 MINUTE)),
       (16, 7, 9, '강지호입니다. REST API 개발은 회원 기능부터 나눠 진행하는 방식으로 제안드려요. 우선 필요한 입력 항목과 화면 흐름을 확인하고 구현 순서와 이번 달 일정을 함께 정하겠습니다.', 1200000, 'REQUESTED', DATE_SUB(@seed_now, INTERVAL 105 MINUTE)),
       (17, 8, 9, '안녕하세요. 박현우입니다. 회원 인증과 데이터 저장 API를 기준으로 작업 범위를 확인하고 싶습니다. 현재 코드가 있다면 JPA 엔티티와 MySQL 테이블 구조부터 함께 살펴보겠습니다.', 1220000, 'SENT', DATE_SUB(@seed_now, INTERVAL 105 MINUTE)),
       (18, 9, 9, '임서아입니다. API가 연결될 화면을 보내 주시면 요청·응답에 필요한 항목을 정리해 드릴게요. 오류가 났을 때의 안내까지 포함할 수 있도록 화면별 동작도 함께 확인하고 싶습니다.', 1240000, 'SENT', DATE_SUB(@seed_now, INTERVAL 105 MINUTE)),
       (19, 1, 10, '안녕하세요. 김민준입니다. 원룸 이사 요청 확인했습니다. 침대 프레임과 책상은 분해 가능한 구조인지 먼저 살펴볼게요. 양쪽 집의 엘리베이터 유무와 가구 사진을 부탁드립니다.', 280000, 'REQUESTED', DATE_SUB(@seed_now, INTERVAL 115 MINUTE)),
       (20, 2, 10, '이서준입니다. 짐을 싣는 곳부터 내려놓을 방까지 이동 경로를 확인해 준비하겠습니다. 엘리베이터 사용 예약이 필요한 건물이라면 관리실에 가능한 시간도 확인해 주세요.', 300000, 'SENT', DATE_SUB(@seed_now, INTERVAL 115 MINUTE)),
       (21, 3, 10, '안녕하세요. 최도윤입니다. 침대와 책상이 현관을 통과하는지 치수를 먼저 확인하면 좋겠습니다. 큰 짐은 보호 포장한 뒤 옮기고 도착한 곳에서 배치까지 도와드려요.', 320000, 'SENT', DATE_SUB(@seed_now, INTERVAL 115 MINUTE)),
       (22, 4, 11, '정수빈입니다. 20평 입주 청소 요청에 맞춰 견적 보내 드립니다. 창틀과 화장실을 꼼꼼하게 살펴보고 주방 후드 상태도 확인하겠습니다. 집 상태를 볼 수 있는 사진이 있으면 부탁드려요.', 230000, 'REQUESTED', DATE_SUB(@seed_now, INTERVAL 125 MINUTE)),
       (23, 5, 11, '안녕하세요. 오지안입니다. 창틀과 욕실을 집중적으로 청소하는 범위로 제안드립니다. 오래된 물때나 실리콘 변색처럼 청소만으로 달라지기 어려운 부분은 시작 전에 설명드리겠습니다.', 250000, 'SENT', DATE_SUB(@seed_now, INTERVAL 125 MINUTE)),
       (24, 6, 11, '윤하윤입니다. 입주 전에 집 안이 비어 있는지와 출입 가능한 시간을 알려 주세요. 작업 후 직접 확인하시기 편하도록 마무리 시간을 미리 안내해 드리겠습니다.', 270000, 'SENT', DATE_SUB(@seed_now, INTERVAL 125 MINUTE)),
       (25, 7, 12, '안녕하세요. 강지호입니다. 요청하신 REST API와 데이터베이스 구성을 함께 상담할 수 있어요. 예약 흐름과 관리자에게 필요한 기능부터 정리해서 구현 범위를 제안드리겠습니다.', 1200000, 'REQUESTED', DATE_SUB(@seed_now, INTERVAL 135 MINUTE)),
       (26, 8, 12, '박현우입니다. Spring Boot·JPA·MySQL 구성으로 개발 가능하며 이번 달 완료를 목표로 범위를 협의하고 싶습니다. 필수 기능과 나중에 추가할 기능을 나눠 알려 주시면 일정 산정에 도움이 됩니다.', 1220000, 'SENT', DATE_SUB(@seed_now, INTERVAL 135 MINUTE)),
       (27, 9, 12, '안녕하세요. 임서아입니다. 사용자가 입력하는 화면과 관리자가 확인하는 화면을 함께 보면 API 범위를 정하기 좋아요. 참고 화면과 필요한 기능 목록을 보내 주시면 연결 작업을 구체적으로 안내하겠습니다.', 1240000, 'SENT', DATE_SUB(@seed_now, INTERVAL 135 MINUTE));

