VALUES (1, 16, DATE_SUB(@seed_now, INTERVAL 105 MINUTE), '자료를 보내 주시면 기능 범위와 예상 일정을 정리해 드릴게요.', DATE_SUB(@seed_now, INTERVAL 6 MINUTE)),
