       (3, 22, DATE_SUB(@seed_now, INTERVAL 125 MINUTE), '사진을 보내 주시면 주방과 욕실의 작업 범위를 확인해 드릴게요.', DATE_SUB(@seed_now, INTERVAL 8 MINUTE)),
       (4, 25, DATE_SUB(@seed_now, INTERVAL 135 MINUTE), '운영 기준을 받으면 예약 데이터 구조부터 설명드리겠습니다.', DATE_SUB(@seed_now, INTERVAL 9 MINUTE));

