INSERT INTO chat_message (chat_room_id, sender_id, type, content, created_at)
VALUES (1, 4, 'TEXT', '안녕하세요. 요청서에 적은 REST API 개발 건으로 상담받고 싶어요.', DATE_SUB(@seed_now, INTERVAL 11 MINUTE)),
       (1, 17, 'TEXT', '안녕하세요. 회원 기능과 예약 기능 중 어떤 부분부터 필요하신가요?', DATE_SUB(@seed_now, INTERVAL 10 MINUTE)),
       (1, 4, 'TEXT', '우선 회원가입과 로그인부터 연결하고 싶어요. 화면은 어느 정도 준비돼 있습니다.', DATE_SUB(@seed_now, INTERVAL 9 MINUTE)),
       (1, 17, 'TEXT', '그럼 기존 화면의 입력 항목부터 확인하겠습니다. 참고할 화면을 보내 주실 수 있을까요?', DATE_SUB(@seed_now, INTERVAL 8 MINUTE)),
       (1, 4, 'TEXT', '네. 화면과 필요한 기능을 정리해서 보내 드릴게요.', DATE_SUB(@seed_now, INTERVAL 7 MINUTE)),
       (1, 17, 'TEXT', '자료를 보내 주시면 기능 범위와 예상 일정을 정리해 드릴게요.', DATE_SUB(@seed_now, INTERVAL 6 MINUTE)),
       (2, 4, 'TEXT', '안녕하세요. 원룸 이사 견적 보고 연락드렸어요. 침대랑 책상도 옮겨야 해요.', DATE_SUB(@seed_now, INTERVAL 12 MINUTE)),
       (2, 11, 'TEXT', '안녕하세요. 침대 프레임과 책상은 분해가 가능한 형태일까요?', DATE_SUB(@seed_now, INTERVAL 11 MINUTE)),
       (2, 4, 'TEXT', '침대는 조립식이고 책상은 다리만 분리할 수 있어요.', DATE_SUB(@seed_now, INTERVAL 10 MINUTE)),
       (2, 11, 'TEXT', '사진을 보면 작업 도구를 미리 준비할 수 있어요. 출발지에 엘리베이터도 있나요?', DATE_SUB(@seed_now, INTERVAL 9 MINUTE)),
       (2, 4, 'TEXT', '네. 엘리베이터 있습니다. 가구 사진도 같이 보내 드릴게요.', DATE_SUB(@seed_now, INTERVAL 8 MINUTE)),
       (2, 11, 'TEXT', '사진 확인 후 포장과 분해·조립 범위를 안내해 드리겠습니다.', DATE_SUB(@seed_now, INTERVAL 7 MINUTE)),
       (3, 4, 'TEXT', '안녕하세요. 입주 청소 견적을 받았는데 창틀도 포함되는지 궁금해요.', DATE_SUB(@seed_now, INTERVAL 13 MINUTE)),
       (3, 14, 'TEXT', '네. 창틀 청소가 포함됩니다. 집 안에 짐이나 가구가 들어와 있을까요?', DATE_SUB(@seed_now, INTERVAL 12 MINUTE)),
       (3, 4, 'TEXT', '아직 빈집이에요. 화장실 두 곳과 주방 후드가 특히 신경 쓰입니다.', DATE_SUB(@seed_now, INTERVAL 11 MINUTE)),
       (3, 14, 'TEXT', '확인했습니다. 오염 상태를 볼 수 있도록 사진을 보내 주시면 작업 시간을 안내해 드릴게요.', DATE_SUB(@seed_now, INTERVAL 10 MINUTE)),
       (3, 4, 'TEXT', '오늘 집에 들러서 사진 찍어 보낼게요.', DATE_SUB(@seed_now, INTERVAL 9 MINUTE)),
       (3, 14, 'TEXT', '사진을 보내 주시면 주방과 욕실의 작업 범위를 확인해 드릴게요.', DATE_SUB(@seed_now, INTERVAL 8 MINUTE)),
       (4, 4, 'TEXT', '안녕하세요. 개발 견적 관련해서 데이터베이스 구성도 함께 상담할 수 있을까요?', DATE_SUB(@seed_now, INTERVAL 14 MINUTE)),
       (4, 17, 'TEXT', '네. 현재 저장할 정보와 화면에서 필요한 기능부터 살펴보면 됩니다.', DATE_SUB(@seed_now, INTERVAL 13 MINUTE)),
       (4, 4, 'TEXT', '회원 정보랑 예약 날짜를 관리하려고 해요. 관리자가 예약을 확인하는 화면도 필요합니다.', DATE_SUB(@seed_now, INTERVAL 12 MINUTE)),
       (4, 17, 'TEXT', '예약 가능 시간과 취소 기준이 정해져 있으면 데이터 구조를 잡기 수월해요.', DATE_SUB(@seed_now, INTERVAL 11 MINUTE)),
       (4, 4, 'TEXT', '운영 방식을 정리해서 공유드릴게요.', DATE_SUB(@seed_now, INTERVAL 10 MINUTE)),
       (4, 17, 'TEXT', '운영 기준을 받으면 예약 데이터 구조부터 설명드리겠습니다.', DATE_SUB(@seed_now, INTERVAL 9 MINUTE));

-- 7. 커뮤니티 글 15개와 댓글 30개. 현재 모델에는 답글 연결 필드가 없습니다.

INSERT INTO post (id, member_id, second_category_id, second_region_id, board_type, title, content, view_count, comment_count, like_count, is_visible, created_at, updated_at)
VALUES (1, 2, 101, 38, 'QUESTION', '첫 이사 전날, 뭘 먼저 챙기면 좋을까요?', '처음 자취방을 옮기는데 어디서부터 짐을 싸야 할지 막막하네요. 옷이랑 책은 상자에 담고 있는데 이사 당일 쓸 물건도 같이 넣어 버릴까 봐 걱정돼요. 먼저 챙겨 두면 좋은 물건이 있을까요?', 11, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2820 MINUTE), DATE_SUB(@seed_now, INTERVAL 2740 MINUTE)),
       (2, 11, 101, 30, 'TIP', '원룸 이사 전에 챙길 다섯 가지', '이사 현장에서 자주 빠뜨리는 준비를 적어 봅니다. ① 관리실에 차량 출입 시간을 알려 주세요. ② 냉장고 안은 미리 비워 주세요. ③ 상자에는 놓을 방을 적어 주세요. ④ 귀중품과 약은 따로 챙겨 주세요. ⑤ 도착한 집에서 쓸 충전기와 세면도구는 마지막까지 손에 두면 편합니다.', 14, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2760 MINUTE), DATE_SUB(@seed_now, INTERVAL 2680 MINUTE)),
       (3, 12, 101, 39, 'PROMOTION', '원룸·소형 이사 상담받고 있어요', '서초·강남·마포 지역의 소형 이사를 진행하고 있습니다. 짐 사진과 출발지·도착지의 층수를 알려 주시면 필요한 차량과 인원을 안내해 드려요. 침대 조립이나 계단 운반이 있다면 처음 상담할 때 같이 말씀해 주세요.', 17, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2700 MINUTE), DATE_SUB(@seed_now, INTERVAL 2620 MINUTE)),
       (4, 3, 102, 38, 'QUESTION', '입주 청소와 가구 배송, 순서가 궁금해요', '청소 날짜를 잡으려는데 침대 배송이 먼저 가능하다고 하네요. 가구가 없는 상태에서 청소하는 게 나을 것 같긴 한데 날짜를 바꾸기가 쉽지 않아요. 큰 가구가 한두 개 있어도 청소가 가능할까요?', 20, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2640 MINUTE), DATE_SUB(@seed_now, INTERVAL 2560 MINUTE)),
       (5, 14, 102, 30, 'TIP', '입주 청소 때 놓치기 쉬운 공간', '바닥만 깨끗해 보여도 창틀 홈과 수납장 안쪽에는 먼지가 남아 있을 수 있어요. 주방 후드 필터와 욕실 배수구도 같이 확인해 보세요. 상담할 때 사진을 보내 주시면 집 상태에 맞는 작업 범위를 설명드리기 좋습니다.', 23, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2580 MINUTE), DATE_SUB(@seed_now, INTERVAL 2500 MINUTE)),
       (6, 15, 102, 39, 'PROMOTION', '주방·욕실 청소, 범위부터 안내드립니다', '후드에 기름때가 쌓였거나 욕실 물때 때문에 고민이라면 사진을 보내 주세요. 소재와 오염 정도를 보고 가능한 작업부터 말씀드립니다. 청소를 마친 뒤에는 함께 둘러보고 빠진 곳이 없는지 확인합니다.', 26, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2520 MINUTE), DATE_SUB(@seed_now, INTERVAL 2440 MINUTE)),
       (7, 4, 139, 38, 'RECRUIT', '공방 예약 사이트를 함께 만들 고수 찾습니다', '작은 도자기 공방을 운영하고 있어요. 지금은 메시지로 예약을 받는데 날짜가 겹치는 일이 생겨서 예약 사이트를 알아보고 있습니다. 휴대폰에서 날짜와 수업을 고를 수 있으면 좋겠어요. 제작 기간과 관리 방법도 상담받고 싶습니다.', 29, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2460 MINUTE), DATE_SUB(@seed_now, INTERVAL 2380 MINUTE)),
       (8, 17, 139, 30, 'TIP', '개발 견적을 받기 전에 정리해 보세요', '어떤 기능이 필요한지 말로 설명하기 어려울 때는 실제 사용하는 순서를 적어 보세요. 예를 들어 날짜 선택 → 인원 선택 → 연락처 입력처럼요. 참고 사이트에서 마음에 드는 부분과 필요 없는 부분을 나눠 주시면 견적 범위를 맞추기 훨씬 수월합니다.', 32, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2400 MINUTE), DATE_SUB(@seed_now, INTERVAL 2320 MINUTE)),
       (9, 18, 139, 39, 'PROMOTION', '기존 화면에 맞는 API 개발을 도와드립니다', '화면은 준비됐는데 회원가입이나 예약 기능을 연결하지 못하고 계신가요? 현재 화면과 필요한 기능을 확인한 뒤 API와 데이터베이스를 구성해 드립니다. 작업 범위와 배포 후 확인할 항목은 상담에서 함께 정합니다.', 35, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2340 MINUTE), DATE_SUB(@seed_now, INTERVAL 2260 MINUTE)),
       (10, 5, 101, 38, 'QUESTION', '이삿날 비 예보가 있는데 괜찮을까요?', '다음 주 이삿날에 비 예보가 떠서 걱정이에요. 책장이랑 컴퓨터가 젖을까 봐 비닐을 더 사 둬야 하나 고민 중입니다. 비 오는 날 이사해 보신 분들은 어떻게 준비하셨나요?', 38, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2280 MINUTE), DATE_SUB(@seed_now, INTERVAL 2200 MINUTE)),
       (11, 13, 101, 30, 'TIP', '큰 가구는 현관 폭도 확인해 주세요', '책장이나 소파를 옮길 때는 가구 크기뿐 아니라 현관과 복도의 폭도 중요합니다. 엘리베이터가 있어도 문을 통과하지 못하는 경우가 있어요. 가구 전체 사진과 이동할 곳의 문 폭을 미리 알려 주시면 분해나 다른 운반 방법이 필요한지 확인해 드릴 수 있습니다.', 41, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2220 MINUTE), DATE_SUB(@seed_now, INTERVAL 2140 MINUTE)),
       (12, 2, 102, 39, 'RECRUIT', '강남 입주 청소 가능한 분 계실까요?', '주말에 이사를 앞두고 있어서 금요일 오후에 청소를 맡기고 싶습니다. 주방과 거실 위주로 생각하고 있고 집은 비어 있어요. 창틀 청소도 포함되는지와 예상 작업 시간을 알고 싶습니다.', 44, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2160 MINUTE), DATE_SUB(@seed_now, INTERVAL 2080 MINUTE)),
       (13, 19, 139, 38, 'PROMOTION', '휴대폰에서도 편한 가게 소개 페이지', '가게 위치와 메뉴를 찾으려고 들어왔는데 화면이 작아서 불편했던 경험이 있나요? 휴대폰에서 읽기 편한 소개 페이지를 만듭니다. 전화·문의 버튼과 지도처럼 자주 쓰는 기능부터 함께 정해요.', 47, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2100 MINUTE), DATE_SUB(@seed_now, INTERVAL 2020 MINUTE)),
       (14, 3, 139, 30, 'QUESTION', '개발 견적에서 유지보수는 따로 보나요?', '사이트 제작 견적을 몇 군데 받았는데 유지보수 범위가 조금씩 다르네요. 문구 수정이나 오류 수정은 보통 어디까지 포함되는지 궁금합니다. 배포 비용도 처음 견적에서 같이 확인하는 게 좋을까요?', 50, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 2040 MINUTE), DATE_SUB(@seed_now, INTERVAL 1960 MINUTE)),
       (15, 5, 139, 39, 'RECRUIT', '작품을 소개할 공방 홈페이지가 필요해요', '만든 작품을 사진과 설명으로 모아 둘 홈페이지를 준비하고 있어요. 주문 기능까지는 필요 없고 문의할 수 있는 창구가 있으면 좋겠습니다. 사진과 글은 제가 나중에 바꿀 수 있는 방식이면 더 좋겠어요.', 53, 2, 0, TRUE, DATE_SUB(@seed_now, INTERVAL 1980 MINUTE), DATE_SUB(@seed_now, INTERVAL 1900 MINUTE));

INSERT INTO post_comment (id, post_id, member_id, content, like_count, created_at, updated_at)
VALUES (1, 1, 11, '이사 당일 쓸 충전기와 세면도구는 작은 가방에 따로 챙겨 두세요. 계약서와 신분증도 상자에 넣지 않고 직접 가지고 계시면 편합니다.', 0, DATE_SUB(@seed_now, INTERVAL 2640 MINUTE), DATE_SUB(@seed_now, INTERVAL 2640 MINUTE)),
       (2, 1, 3, '저도 첫 이사 때 상자에 가위를 넣어서 한참 찾았어요. 가위랑 테이프는 마지막까지 꺼내 두시는 걸 추천해요.', 0, DATE_SUB(@seed_now, INTERVAL 2639 MINUTE), DATE_SUB(@seed_now, INTERVAL 2639 MINUTE)),
       (3, 2, 12, '냉장고 비우는 걸 놓치는 분들이 많더라고요. 냉동식품은 전날까지 정리해 두면 당일 포장이 훨씬 수월합니다.', 0, DATE_SUB(@seed_now, INTERVAL 2580 MINUTE), DATE_SUB(@seed_now, INTERVAL 2580 MINUTE)),
       (4, 2, 4, '상자마다 방 이름을 적는 건 생각 못 했네요. 도착해서 전부 다시 열어 볼 뻔했어요. 준비할 때 참고할게요.', 0, DATE_SUB(@seed_now, INTERVAL 2579 MINUTE), DATE_SUB(@seed_now, INTERVAL 2579 MINUTE)),
       (5, 3, 11, '계단 작업은 층수뿐 아니라 폭도 중요하죠. 상담할 때 계단 사진까지 받으면 현장 준비에 도움이 될 것 같아요.', 0, DATE_SUB(@seed_now, INTERVAL 2520 MINUTE), DATE_SUB(@seed_now, INTERVAL 2520 MINUTE)),
       (6, 3, 5, '큰 책상 하나만 옮기는 경우도 상담할 수 있나요? 분해가 필요한 책상이라 차량만 빌리기는 어려울 것 같아서요.', 0, DATE_SUB(@seed_now, INTERVAL 2519 MINUTE), DATE_SUB(@seed_now, INTERVAL 2519 MINUTE)),
       (7, 4, 14, '가능하면 청소를 먼저 하는 편이 좋지만 가구가 있어도 작업은 할 수 있어요. 다만 가구 뒤나 아래는 접근이 어려울 수 있어 위치를 미리 알려 주세요.', 0, DATE_SUB(@seed_now, INTERVAL 2460 MINUTE), DATE_SUB(@seed_now, INTERVAL 2460 MINUTE)),
       (8, 4, 2, '저는 배송을 하루 미뤘는데 청소 후 먼지가 가라앉을 시간도 있어서 괜찮았어요. 일정 조정이 된다면 청소 먼저 추천해요.', 0, DATE_SUB(@seed_now, INTERVAL 2459 MINUTE), DATE_SUB(@seed_now, INTERVAL 2459 MINUTE)),
       (9, 5, 15, '수납장 안쪽은 문을 닫으면 잘 안 보이죠. 작업 후 확인하실 때 서랍도 한 번씩 열어 보시면 좋습니다.', 0, DATE_SUB(@seed_now, INTERVAL 2400 MINUTE), DATE_SUB(@seed_now, INTERVAL 2400 MINUTE)),
       (10, 5, 3, '창틀은 눈에 보이는 부분만 생각했는데 홈까지 확인해야겠네요. 청소 상담할 때 사진부터 찍어 둬야겠어요.', 0, DATE_SUB(@seed_now, INTERVAL 2399 MINUTE), DATE_SUB(@seed_now, INTERVAL 2399 MINUTE)),
       (11, 6, 14, '후드와 욕실은 소재에 따라 작업 방법이 달라지죠. 가능한 범위를 먼저 설명해 주신다는 점이 좋네요.', 0, DATE_SUB(@seed_now, INTERVAL 2340 MINUTE), DATE_SUB(@seed_now, INTERVAL 2340 MINUTE)),
       (12, 6, 4, '오래된 후드라 필터에 기름때가 꽤 있어요. 모델명과 사진을 같이 보내 드리면 상담에 도움이 될까요?', 0, DATE_SUB(@seed_now, INTERVAL 2339 MINUTE), DATE_SUB(@seed_now, INTERVAL 2339 MINUTE)),
       (13, 7, 17, '같은 시간에 여러 분이 예약하는 경우도 있어서 중복 예약을 막는 방식이 중요해요. 수업별 정원과 취소 기준도 함께 알려 주시면 좋겠습니다.', 0, DATE_SUB(@seed_now, INTERVAL 2280 MINUTE), DATE_SUB(@seed_now, INTERVAL 2280 MINUTE)),
       (14, 7, 5, '저도 작은 가게를 운영하는데 예약 변경이 제일 번거롭더라고요. 손님이 직접 변경할 수 있는지도 상담해 보세요.', 0, DATE_SUB(@seed_now, INTERVAL 2279 MINUTE), DATE_SUB(@seed_now, INTERVAL 2279 MINUTE)),
       (15, 8, 18, '참고 화면에 필요한 기능을 표시해 주시면 놓치는 부분이 줄어요. 관리자 화면에서 해야 할 일도 같이 정리하면 좋습니다.', 0, DATE_SUB(@seed_now, INTERVAL 2220 MINUTE), DATE_SUB(@seed_now, INTERVAL 2220 MINUTE)),
       (16, 8, 2, '기능 이름만 적으려니 어려웠는데 사용하는 순서로 쓰면 되겠네요. 예약받는 과정을 한번 정리해 볼게요.', 0, DATE_SUB(@seed_now, INTERVAL 2219 MINUTE), DATE_SUB(@seed_now, INTERVAL 2219 MINUTE)),
       (17, 9, 17, '화면이 먼저 있다면 오류가 났을 때 보여 줄 안내도 같이 정해 두면 좋겠네요. 정상 동작만 맞추면 뒤에서 수정이 생기더라고요.', 0, DATE_SUB(@seed_now, INTERVAL 2160 MINUTE), DATE_SUB(@seed_now, INTERVAL 2160 MINUTE)),
       (18, 9, 3, '로그인 화면은 만들어 뒀는데 회원 정보가 저장되지 않아 막혀 있었어요. 이런 경우에도 기존 화면을 살려서 작업할 수 있을까요?', 0, DATE_SUB(@seed_now, INTERVAL 2159 MINUTE), DATE_SUB(@seed_now, INTERVAL 2159 MINUTE)),
       (19, 10, 11, '컴퓨터는 전원을 분리하고 물이 닿지 않도록 포장해 주세요. 현장에서는 차량까지 이동하는 구간을 짧게 잡고 가구 덮개도 준비합니다.', 0, DATE_SUB(@seed_now, INTERVAL 2100 MINUTE), DATE_SUB(@seed_now, INTERVAL 2100 MINUTE)),
       (20, 10, 4, '비 오는 날 이사한 적 있는데 수건을 넉넉히 챙겨서 유용했어요. 현관 쪽 바닥에 물기가 생겨서 계속 닦게 되더라고요.', 0, DATE_SUB(@seed_now, INTERVAL 2099 MINUTE), DATE_SUB(@seed_now, INTERVAL 2099 MINUTE)),
       (21, 11, 11, '문 폭을 잴 때 손잡이나 돌출된 부분도 같이 봐야 해요. 사진 한 장이 있으면 설명만 듣는 것보다 판단하기 쉽습니다.', 0, DATE_SUB(@seed_now, INTERVAL 2040 MINUTE), DATE_SUB(@seed_now, INTERVAL 2040 MINUTE)),
       (22, 11, 5, '소파 길이만 재고 있었는데 복도에서 꺾이는 구간도 봐야겠네요. 이사 전에 치수부터 다시 확인해 볼게요.', 0, DATE_SUB(@seed_now, INTERVAL 2039 MINUTE), DATE_SUB(@seed_now, INTERVAL 2039 MINUTE)),
       (23, 12, 14, '금요일 오후 일정을 확인해 드릴 수 있어요. 평수와 창문 개수를 알려 주시면 작업 시간과 창틀 청소 범위를 안내해 드리겠습니다.', 0, DATE_SUB(@seed_now, INTERVAL 1980 MINUTE), DATE_SUB(@seed_now, INTERVAL 1980 MINUTE)),
       (24, 12, 3, '입주 전에 청소 시간을 넉넉히 잡는 게 좋더라고요. 창문이 많으면 예상보다 오래 걸릴 수 있으니 꼭 물어보세요.', 0, DATE_SUB(@seed_now, INTERVAL 1979 MINUTE), DATE_SUB(@seed_now, INTERVAL 1979 MINUTE)),
       (25, 13, 17, '가게 소개 페이지라면 영업시간과 휴무일도 눈에 잘 들어와야겠네요. 문의 버튼까지 가는 동선이 짧으면 더 편할 것 같아요.', 0, DATE_SUB(@seed_now, INTERVAL 1920 MINUTE), DATE_SUB(@seed_now, INTERVAL 1920 MINUTE)),
       (26, 13, 3, '가게 메뉴가 자주 바뀌는데 직접 수정할 수 있는지도 궁금해요. 개발 지식이 없어도 관리할 수 있는 방식이 있을까요?', 0, DATE_SUB(@seed_now, INTERVAL 1919 MINUTE), DATE_SUB(@seed_now, INTERVAL 1919 MINUTE)),
       (27, 14, 17, '오류 수정과 새 기능 추가는 범위를 나눠서 확인하는 편이 좋아요. 서버·도메인 비용과 지원 기간도 견적서에 적어 달라고 요청해 보세요.', 0, DATE_SUB(@seed_now, INTERVAL 1860 MINUTE), DATE_SUB(@seed_now, INTERVAL 1860 MINUTE)),
       (28, 14, 4, '저도 견적 받을 때 호스팅 비용을 놓쳤었어요. 매달 나가는 금액이 있는지 먼저 물어보시면 비교하기 편해요.', 0, DATE_SUB(@seed_now, INTERVAL 1859 MINUTE), DATE_SUB(@seed_now, INTERVAL 1859 MINUTE)),
       (29, 15, 17, '사진과 글을 직접 바꾸시려면 간단한 관리 화면이 있으면 좋겠어요. 작품 분류가 필요한지도 먼저 정해 보세요.', 0, DATE_SUB(@seed_now, INTERVAL 1800 MINUTE), DATE_SUB(@seed_now, INTERVAL 1800 MINUTE)),
       (30, 15, 2, '저는 사진을 한꺼번에 올리면 느려질까 걱정되더라고요. 작품 사진 용량이나 권장 크기도 같이 안내받으면 좋을 것 같아요.', 0, DATE_SUB(@seed_now, INTERVAL 1799 MINUTE), DATE_SUB(@seed_now, INTERVAL 1799 MINUTE));

